CREATE TABLE backup_volume (id VARCHAR(80) PRIMARY KEY, name VARCHAR(240) NOT NULL UNIQUE, capacity_gb NUMERIC(14,3), occupied_gb NUMERIC(14,3), reported_free_gb NUMERIC(14,3), note TEXT, measurement_source VARCHAR(40) NOT NULL, measured_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE legacy_item (id VARCHAR(120) PRIMARY KEY, volume_name VARCHAR(240) NOT NULL, label TEXT, created_text VARCHAR(120), test_status TEXT, size_text VARCHAR(100), unit VARCHAR(32), source_sheet VARCHAR(40) NOT NULL, source_row INTEGER NOT NULL, kind VARCHAR(40) NOT NULL DEFAULT 'LEGACY_AGGREGATE', UNIQUE(source_sheet, source_row));
CREATE INDEX idx_legacy_volume ON legacy_item(volume_name); CREATE INDEX idx_legacy_label ON legacy_item USING gin (to_tsvector('simple', coalesce(label,'')));
CREATE TABLE managed_item (id UUID PRIMARY KEY, volume_id VARCHAR(80) NOT NULL REFERENCES backup_volume(id), parent_id UUID REFERENCES managed_item(id), relative_path TEXT NOT NULL, display_name VARCHAR(255) NOT NULL, content_type VARCHAR(160), size_bytes BIGINT NOT NULL CHECK(size_bytes>=0), sha256 CHAR(64), storage_key UUID NOT NULL UNIQUE, created_by VARCHAR(160) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(volume_id, relative_path));
CREATE INDEX idx_managed_parent ON managed_item(parent_id); CREATE INDEX idx_managed_hash ON managed_item(sha256) WHERE sha256 IS NOT NULL; CREATE INDEX idx_managed_name ON managed_item(display_name);
CREATE TABLE app_user (id UUID PRIMARY KEY, username VARCHAR(160) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL CHECK(role IN ('ADMIN','OPERATOR','READER')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_event (id UUID PRIMARY KEY, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), actor VARCHAR(160), volume_id VARCHAR(80), item_id UUID, action VARCHAR(60) NOT NULL, result VARCHAR(30) NOT NULL, details JSONB);
CREATE INDEX idx_audit_date ON audit_event(occurred_at DESC); CREATE INDEX idx_audit_volume ON audit_event(volume_id);
CREATE TABLE app_setting (setting_key VARCHAR(120) PRIMARY KEY, setting_value JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
